const STORAGE_KEY = "notepad-content";

let _beforeUnloadHandler = null;

export function loadContent() {
    return localStorage.getItem(STORAGE_KEY) ?? "";
}

export function saveContent(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function clearContent() {
    localStorage.removeItem(STORAGE_KEY);
}

export function enableBeforeUnload() {
    if (_beforeUnloadHandler) return;
    _beforeUnloadHandler = (e) => {
        e.preventDefault();
    };
    window.addEventListener("beforeunload", _beforeUnloadHandler);
}

export function disableBeforeUnload() {
    if (!_beforeUnloadHandler) return;
    window.removeEventListener("beforeunload", _beforeUnloadHandler);
    _beforeUnloadHandler = null;
}

@page "/notepad"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IJSRuntime JS

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea class="form-control mb-3" rows="10" @bind="content" @bind:event="oninput"></textarea>

<div class="d-flex align-items-center gap-2 mb-3">
    <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
    <button class="btn btn-danger" @onclick="ClearAsync">Clear</button>
    @if (lastSavedAt is not null)
    {
        <span class="text-muted ms-2">Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = "";
    private string savedContent = "";
    private DateTime? lastSavedAt;
    private IJSObjectReference? module;
    private System.Threading.Timer? autoSaveTimer;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", $"./{Assets["Components/Pages/Notepad.razor.js"]}");

            var loaded = await module.InvokeAsync<string>("loadContent");
            if (!string.IsNullOrEmpty(loaded))
            {
                content = loaded;
                savedContent = loaded;
                StateHasChanged();
            }

            autoSaveTimer = new System.Threading.Timer(
                async _ => await InvokeAsync(AutoSaveAsync),
                null,
                TimeSpan.FromSeconds(30),
                TimeSpan.FromSeconds(30));
        }

        await UpdateBeforeUnloadAsync();
    }

    private bool HasUnsavedChanges => content != savedContent;

    private async Task UpdateBeforeUnloadAsync()
    {
        if (module is null) return;

        if (HasUnsavedChanges)
            await module.InvokeVoidAsync("enableBeforeUnload");
        else
            await module.InvokeVoidAsync("disableBeforeUnload");
    }

    private async Task AutoSaveAsync()
    {
        if (!HasUnsavedChanges || module is null) return;
        await SaveContentAsync();
        StateHasChanged();
    }

    private async Task SaveNowAsync()
    {
        if (module is null) return;
        await SaveContentAsync();
    }

    private async Task SaveContentAsync()
    {
        if (module is null) return;
        await module.InvokeVoidAsync("saveContent", content);
        savedContent = content;
        lastSavedAt = DateTime.Now;
    }

    private async Task ClearAsync()
    {
        if (module is null) return;
        content = "";
        savedContent = "";
        lastSavedAt = null;
        await module.InvokeVoidAsync("clearContent");
    }

    public async ValueTask DisposeAsync()
    {
        if (autoSaveTimer is not null)
            await autoSaveTimer.DisposeAsync();

        if (module is not null)
        {
            await module.InvokeVoidAsync("disableBeforeUnload");
            await module.DisposeAsync();
        }
    }
}

